import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    if bins.size == 0:
        return np.array([], dtype=float)
    max_cap = np.max(bins)
    is_empty = (bins == max_cap)
    scores = np.where(rem >= 0, np.exp(-rem / 0.2), -np.inf)
    scores = np.where(is_empty & (rem >= 0), scores * 0.1, scores)
    return scores
